package com.euvcraft.lithmod.mc.gametest;
import static com.euvcraft.lithmod.mc.gametest.T4RuntimeFixtures.*;
import com.euvcraft.lithmod.core.*;import com.euvcraft.lithmod.mc.*;import com.euvcraft.lithmod.mc.registry.*;import com.euvcraft.lithmod.mc.machine.cleaner.*;
import net.minecraft.core.*;import net.minecraft.core.component.DataComponents;import net.minecraft.core.registries.Registries;import net.minecraft.resources.*;import net.minecraft.gametest.framework.*;
import net.minecraft.network.chat.Component;import net.minecraft.server.level.*;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.material.Fluids;import net.minecraft.world.item.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.phys.AABB;
import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.event.RegisterGameTestsEvent;import net.neoforged.neoforge.registries.DeferredRegister;import net.neoforged.neoforge.capabilities.Capabilities;import net.neoforged.neoforge.transfer.fluid.FluidResource;import net.neoforged.neoforge.transfer.transaction.Transaction;
import java.util.*;import java.util.function.Consumer;
public final class FoupCleanerGameTests {
 private static final DeferredRegister<Consumer<GameTestHelper>> FUNCTIONS=DeferredRegister.create(Registries.TEST_FUNCTION,"lithmod");
 private static final Map<String,Consumer<GameTestHelper>> CASES=new LinkedHashMap<>();
 static {add("admission",FoupCleanerGameTests::admission);add("disposal",FoupCleanerGameTests::disposal);add("power",FoupCleanerGameTests::power);add("buckets",FoupCleanerGameTests::buckets);add("fluids",FoupCleanerGameTests::fluids);add("outputs",FoupCleanerGameTests::outputs);add("reload",FoupCleanerGameTests::reload);add("pending_reload",FoupCleanerGameTests::pendingReload);add("break_active",FoupCleanerGameTests::breakActive);add("break_committed",FoupCleanerGameTests::breakCommitted);add("changed_input",FoupCleanerGameTests::changedInput);}
 private static void add(String id,Consumer<GameTestHelper> f){id="foup_cleaner_"+id;CASES.put(id,f);FUNCTIONS.register(id,()->f);}
 public static void register(IEventBus bus){FUNCTIONS.register(bus);bus.addListener((Consumer<RegisterGameTestsEvent>)event->{Holder<TestEnvironmentDefinition<?>> env=event.registerEnvironment(Identifier.parse("lithmod:foup_cleaner"),new TestEnvironmentDefinition[0]);var data=new TestData<>(env,Level.OVERWORLD,Identifier.withDefaultNamespace("empty"),400,0,true,Rotation.NONE,false,1,1,false,0);for(var name:CASES.keySet()){var id=Identifier.fromNamespaceAndPath("lithmod",name);event.registerTest(id,new FunctionGameTestInstance(ResourceKey.<Consumer<GameTestHelper>>create(Registries.TEST_FUNCTION,id),data));}});}
 private record Cell(ServerLevel level,BlockPos pos,FoupCleanerBlockEntity c) implements AutoCloseable {AABB area(){return new AABB(pos).inflate(2);}public void close(){if(level.getBlockEntity(pos) instanceof FoupCleanerBlockEntity b)b.clearContent();level.setBlock(pos,Blocks.AIR.defaultBlockState(),3);for(var e:level.getEntitiesOfClass(ItemEntity.class,area()))e.discard();}}
 private static Cell cell(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(2,2,2));l.setBlock(p,FoupCleanerMachines.BLOCK.get().defaultBlockState(),3);var c=(FoupCleanerBlockEntity)l.getBlockEntity(p);c.serverTick();c.setStoredEnergy(40000);c.water.fill(16000,false);return new Cell(l,p,c);}
 private static void ticks(FoupCleanerBlockEntity c,int n){for(int i=0;i<n;i++)c.serverTick();}
 private static void admission(GameTestHelper h){try(var f=cell(h)){var c=f.c;check(h,!c.start(),"Empty refuses");c.setSlot(0,fresh(3,WaferSubstrate.ORDINARY));ticks(c,10);eq(h,0,c.progress(),"No automatic disposal");eq(h,16000,c.water.amount(),"Idle uses no water");c.setSlot(0,new ItemStack(ModItems.FOUP_MK1.get()));check(h,!c.start(),"Empty carrier refuses");c.setSlot(0,new ItemStack(Items.DIAMOND));check(h,!c.start(),"Wrong input refuses");c.setSlot(0,fresh(3,WaferSubstrate.PURE));check(h,c.start(),"Nonempty accepts");check(h,!c.start(),"Repeated button cannot reserve twice");eq(h,15000,c.water.amount(),"Water reserved once");}h.succeed();}
 private static void disposal(GameTestHelper h){for(var item:List.of(ModItems.FOUP_MK1.get(),ModItems.FOUP_MK2.get()))try(var f=cell(h)){var c=f.c;var source=FoupItems.trustedContentsOf(complete(5,"compute",1));var stack=FoupItems.with(item,source);stack.set(DataComponents.CUSTOM_NAME,Component.literal("My carrier"));c.setSlot(0,stack);check(h,c.start(),"Processed lot accepts");ticks(c,200);check(h,!c.hasJob()&&c.slot(0).isEmpty(),"Single completion");var result=c.slot(2);var lot=FoupItems.trustedContentsOf(result);check(h,result.is(item)&&lot.isEmpty()&&lot.capacity()==source.capacity()&&!lot.lotId().equals(source.lotId()),"Same carrier, fresh empty lot");check(h,Component.literal("My carrier").equals(result.get(DataComponents.CUSTOM_NAME)),"Carrier custom name retained");eq(h,3,c.slot(3).getCount(),"One scrap per wafer");eq(h,36000,c.buffer().getAmountAsLong(),"200 paid ticks");eq(h,15000,c.water.amount(),"One ordinary-water batch");}h.succeed();}
 private static void power(GameTestHelper h){try(var f=cell(h)){var c=f.c;c.setSlot(0,fresh(2,WaferSubstrate.PURE));check(h,c.start(),"Starts");c.setStoredEnergy(19);ticks(c,5);eq(h,0,c.progress(),"Insufficient tick FE pauses");eq(h,19,c.buffer().getAmountAsLong(),"Partial FE rolls back");c.setStoredEnergy(20);c.serverTick();eq(h,1,c.progress(),"Refill resumes");eq(h,0,c.buffer().getAmountAsLong(),"Exactly one paid tick");c.setStoredEnergy(3980);ticks(c,199);eq(h,2,c.slot(3).getCount(),"Finishes after resumed ticks");eq(h,15000,c.water.amount(),"No second water reservation");}h.succeed();}
 private static void buckets(GameTestHelper h){try(var f=cell(h)){var c=f.c;c.water.restoreAmount(0);c.setSlot(1,new ItemStack(Items.WATER_BUCKET));c.setSlot(4,new ItemStack(Items.BUCKET,16));c.serverTick();eq(h,0,c.water.amount(),"Full empty-bucket output blocks fill");check(h,c.slot(1).is(Items.WATER_BUCKET),"Unspent water bucket");c.clearSlot(4);c.serverTick();eq(h,1000,c.water.amount(),"Bucket fills exactly 1000mB");check(h,c.slot(1).isEmpty()&&c.slot(4).is(Items.BUCKET)&&c.slot(4).getCount()==1,"One returned bucket");}h.succeed();}
 private static void fluids(GameTestHelper h){try(var f=cell(h)){var c=f.c;c.water.restoreAmount(0);var retained=f.level.getCapability(Capabilities.Fluid.BLOCK,f.pos,Direction.NORTH);check(h,retained!=null,"Real fluid capability");try(var tx=Transaction.openRoot()){eq(h,1000,retained.insert(0,FluidResource.of(Fluids.WATER),1000,tx),"Simulation accepts");}eq(h,0,c.water.amount(),"Transaction abort restores water");for(var side:Direction.values()){var cap=f.level.getCapability(Capabilities.Fluid.BLOCK,f.pos,side);check(h,cap!=null,"All faces");try(var tx=Transaction.openRoot()){eq(h,0,cap.insert(0,FluidResource.of(Fluids.LAVA),1000,tx),"Wrong fluid refuses");eq(h,1000,cap.insert(0,FluidResource.of(Fluids.WATER),1000,tx),"Water accepts");tx.commit();}check(h,f.level.getCapability(Capabilities.Item.BLOCK,f.pos,side)==null,"No destructive item automation");}eq(h,6000,c.water.amount(),"Shared tank across faces");var fe=f.level.getCapability(Capabilities.Energy.BLOCK,f.pos,Direction.UP);try(var tx=Transaction.openRoot()){eq(h,0,fe.extract(1000,tx),"External FE extraction denied");}f.level.setBlock(f.pos,Blocks.AIR.defaultBlockState(),3);try(var tx=Transaction.openRoot()){eq(h,0,retained.insert(0,FluidResource.of(Fluids.WATER),1,tx),"Stale fluid lens closes");eq(h,0,fe.insert(1,tx),"Stale FE lens closes");tx.commit();}}h.succeed();}
 private static void outputs(GameTestHelper h){try(var f=cell(h)){var c=f.c;c.setSlot(0,fresh(70,WaferSubstrate.ORDINARY));check(h,c.start(),"70 wafers accepts");c.setSlot(2,new ItemStack(Items.DIRT));ticks(c,220);eq(h,200,c.progress(),"Finished work waits for clean output");eq(h,36000,c.buffer().getAmountAsLong(),"Blocked completion incurs no further FE");eq(h,70,FoupItems.trustedContentsOf(c.slot(0)).size(),"Wafers intact until output unblocks");c.clearSlot(2);c.serverTick();eq(h,64,c.slot(3).getCount(),"First full waste stack");eq(h,6,c.pendingScrap(),"Excess waste retained");check(h,c.slot(2).isEmpty()&&c.hasJob(),"Carrier locked until remaining waste emitted");ticks(c,10);eq(h,6,c.pendingScrap(),"Blocked waste never lost");c.clearSlot(3);c.serverTick();eq(h,6,c.slot(3).getCount(),"Final waste stack");check(h,!c.slot(2).isEmpty()&&!c.hasJob(),"Exactly one clean carrier finishes");}h.succeed();}
 private static FoupCleanerBlockEntity reload(Cell f){var tag=save(f.level,f.c);f.level.removeBlockEntity(f.pos);var c=new FoupCleanerBlockEntity(f.pos,f.level.getBlockState(f.pos));f.level.setBlockEntity(c);load(f.level,c,tag);return c;}
 private static void reload(GameTestHelper h){try(var f=cell(h)){f.c.setSlot(0,fresh(4,WaferSubstrate.PURE));check(h,f.c.start(),"Starts");ticks(f.c,80);var c=reload(f);eq(h,80,c.progress(),"Paid progress persists");eq(h,15000,c.water.amount(),"Reserved water persists");ticks(c,120);eq(h,4,c.slot(3).getCount(),"Reload finishes exactly once");eq(h,36000,c.buffer().getAmountAsLong(),"No replayed FE ticks");}h.succeed();}
 private static void pendingReload(GameTestHelper h){try(var f=cell(h)){f.c.setSlot(0,fresh(130,WaferSubstrate.PURE));check(h,f.c.start(),"Starts");ticks(f.c,200);var c=reload(f);eq(h,66,c.pendingScrap(),"Pending waste persists");eq(h,0,FoupItems.trustedContentsOf(c.slot(0)).size(),"Persisted carrier already emptied");c.clearSlot(3);c.serverTick();eq(h,64,c.slot(3).getCount(),"Second waste stack");eq(h,2,c.pendingScrap(),"Final pending");c.clearSlot(3);c.serverTick();eq(h,2,c.slot(3).getCount(),"All130 accounted as64+64+2");check(h,!c.hasJob()&&!c.slot(2).isEmpty(),"Single clean carrier");}h.succeed();}
 private static void breakActive(GameTestHelper h){try(var f=cell(h)){f.c.setSlot(0,fresh(7,WaferSubstrate.ORDINARY));check(h,f.c.start(),"Starts");ticks(f.c,30);f.level.setBlock(f.pos,Blocks.AIR.defaultBlockState(),3);int carriers=0,scrap=0;for(var e:f.level.getEntitiesOfClass(ItemEntity.class,f.area())){var s=e.getItem();if(FoupCleanerBlockEntity.isFoup(s)){carriers+=s.getCount();eq(h,7,FoupItems.trustedContentsOf(s).size(),"Unfinished wafers returned intact");}if(s.is(FoupCleanerMachines.WAFER_SCRAP.get()))scrap+=s.getCount();}eq(h,1,carriers,"One carrier, no fingerprint copy");eq(h,0,scrap,"No unpaid disposal waste");}h.succeed();}
 private static void breakCommitted(GameTestHelper h){try(var f=cell(h)){f.c.setSlot(0,fresh(130,WaferSubstrate.ORDINARY));check(h,f.c.start(),"Starts");ticks(f.c,200);f.level.setBlock(f.pos,Blocks.AIR.defaultBlockState(),3);int carriers=0,scrap=0;for(var e:f.level.getEntitiesOfClass(ItemEntity.class,f.area())){var s=e.getItem();if(FoupCleanerBlockEntity.isFoup(s)){carriers+=s.getCount();eq(h,0,FoupItems.trustedContentsOf(s).size(),"No discarded wafer revival");}if(s.is(FoupCleanerMachines.WAFER_SCRAP.get()))scrap+=s.getCount();}eq(h,1,carriers,"One emptied carrier");eq(h,130,scrap,"Physical plus pending waste all drops");}h.succeed();}
 private static void changedInput(GameTestHelper h){try(var f=cell(h)){var c=f.c;c.setSlot(0,fresh(2,WaferSubstrate.PURE));check(h,c.start(),"Starts");ticks(c,5);c.setSlot(0,fresh(9,WaferSubstrate.ORDINARY));long fe=c.buffer().getAmountAsLong();c.serverTick();check(h,!c.hasJob(),"Changed input cancels uncommitted job");eq(h,9,FoupItems.trustedContentsOf(c.slot(0)).size(),"Replacement untouched");eq(h,fe,c.buffer().getAmountAsLong(),"No additional FE");eq(h,15000,c.water.amount(),"Spent water not refunded");}h.succeed();}
 private FoupCleanerGameTests(){}
}
